// LabelNarrow answers with `p` and everything else that narrows a
// read of a Label: the rows that have not been erased, and whatever
// `scope` says of those.
//
// Every read this package makes goes through it, and a read written by
// hand should too -- a List is the one read nothing generates, and so the
// one that would otherwise answer with rows nobody should be given.
func LabelNarrow(ctx context.Context, scope Scope, p predicate.Label) (predicate.Label, error) {
	ps := make([]predicate.Label, 0, 3)

	// A row that was erased is not a row a read answers with.
	ps = append(ps, label.DateErasedIsNil())
	if p != nil {
		ps = append(ps, p)
	}
	if scope != nil {
		q, err := scope.LabelScope(ctx)
		if err != nil {
			return nil, err
		}
		if q != nil {
			ps = append(ps, q)
		}
	}

	switch len(ps) {
	case 0:
		return nil, nil
	case 1:
		return ps[0], nil
	default:
		return label.And(ps...), nil
	}
}

