type AttachmentServiceServer struct {
	Store

	rove.UnimplementedAttachmentServiceServer
}

// NewAttachmentServiceServer answers with a server that runs its queries with `db`.
//
// It takes the options of [Server] so that what is built here can be told
// where to report its writes and what it may see. Built without them, it
// reports nowhere and sees everything.
func NewAttachmentServiceServer(db *ent.Client, opts ...Option) rove.AttachmentServiceServer {
	s := Server{Store: Store{Db: db}}
	for _, opt := range opts {
		opt(&s)
	}
	return AttachmentServiceServer{Store: s.Store}
}

// AttachmentNarrow answers with `p` and everything else that narrows a
// read of a Attachment: the rows that have not been erased, and whatever
// `scope` says of those.
//
// Every read this package makes goes through it, and a read written by
// hand should too -- a List is the one read nothing generates, and so the
// one that would otherwise answer with rows nobody should be given.
func AttachmentNarrow(ctx context.Context, scope Scope, p predicate.Attachment) (predicate.Attachment, error) {
	ps := make([]predicate.Attachment, 0, 3)

	// A row that was erased is not a row a read answers with.
	ps = append(ps, attachment.DateErasedIsNil())
	if p != nil {
		ps = append(ps, p)
	}
	if scope != nil {
		q, err := scope.AttachmentScope(ctx)
		if err != nil {
			return nil, err
		}
		if q != nil {
			ps = append(ps, q)
		}
	}

	switch len(ps) {
	case 0:
		return nil, nil
	case 1:
		return ps[0], nil
	default:
		return attachment.And(ps...), nil
	}
}

// narrow is [AttachmentNarrow] with this server's own scope.
func (s AttachmentServiceServer) narrow(ctx context.Context, p predicate.Attachment) (predicate.Attachment, error) {
	return AttachmentNarrow(ctx, s.Scope, p)
}

func (s AttachmentServiceServer) snapshot(ctx context.Context, p predicate.Attachment, lock bool) (*ent.Attachment, error) {
	q := s.Db.Attachment.Query().Where(p)
	q.Modify(func(q *sql.Selector) {
		if lock && s.Db.Dialect() != dialect.SQLite {
			q.ForUpdate()
		}
	})
	return q.Only(ctx)
}
func (s AttachmentServiceServer) image(v *rove.Attachment) *rove.Attachment {
	if v == nil {
		return nil
	}
	out := proto.Clone(v).(*rove.Attachment)
	m := out.ProtoReflect()
	{
		f := m.Descriptor().Fields().ByNumber(2)
		if m.Has(f) {
			trim := func(r protoreflect.Message) {
				r.Range(func(f protoreflect.FieldDescriptor, _ protoreflect.Value) bool {
					if f.Number() != 1 {
						r.Clear(f)
					}
					return true
				})
			}
			trim(m.Get(f).Message())
		}
	}
	return out
}
